import {createStudy,clamp,downloadSVG} from './core.js';
const study=createStudy({id:7,title:'Liquid Letter',category:'Typography / Refraction',accent:'#fff4dd',background:'#ff5bbd',foreground:'#171117'});
const art=document.querySelector('#liquid-art'),noise=document.querySelector('#liquid-turbulence'),map=document.querySelector('#liquid-displace'),ripples=document.querySelector('#liquid-ripples'),input=document.querySelector('#liquid-input');
const rings=[],NS='http://www.w3.org/2000/svg';let x=600,y=350,amplitude=36,lastDrop=0;
function drop(px=x,py=y){const circle=document.createElementNS(NS,'circle');circle.setAttribute('cx',px);circle.setAttribute('cy',py);circle.setAttribute('r',3);ripples.append(circle);rings.push({circle,age:0});while(rings.length>9){rings.shift().circle.remove()}study.invalidate()}
function draw({dt=0,time=0}={}){const moving=study.running();noise.setAttribute('baseFrequency',`${(.006+Math.sin(time*.31)*.0015).toFixed(5)} ${(.012+Math.cos(time*.23)*.002).toFixed(5)}`);map.setAttribute('scale',String(amplitude*(.7+.3*Math.sin(time*.67))));document.querySelector('#liquid-waves').setAttribute('transform',`rotate(${Math.sin(time*.2)*9} 600 350)`);document.querySelector('#liquid-pointer').setAttribute('cx',x);document.querySelector('#liquid-pointer').setAttribute('cy',y);for(let i=rings.length-1;i>=0;i--){const ring=rings[i];ring.age+=moving?dt:0;ring.circle.setAttribute('r',String(8+ring.age*155));ring.circle.setAttribute('stroke-opacity',String(clamp(1-ring.age/2,0,1)));if(ring.age>2){ring.circle.remove();rings.splice(i,1)}}}
function locate(event){const matrix=art.getScreenCTM();if(!matrix)return false;let point;try{point=new DOMPoint(event.clientX,event.clientY).matrixTransform(matrix.inverse())}catch{return false}if(!Number.isFinite(point.x)||!Number.isFinite(point.y))return false;x=point.x;y=point.y;return true}
const move=event=>{if(!locate(event))return;if(study.running()&&event.timeStamp-lastDrop>100){lastDrop=event.timeStamp;drop()}study.invalidate()};
art.addEventListener('pointermove',move);art.addEventListener('pointerdown',event=>{if(locate(event))drop()});
input.addEventListener('input',()=>{const word=input.value.toUpperCase()||'FLOW';document.querySelector('#liquid-word').textContent=word;document.querySelector('#liquid-pattern-word').textContent=word;document.querySelector('#liquid-description').textContent=`The word ${word} appears as distorted ink on a pink surface, with fine contour lines and ripple rings.`;study.invalidate()});
document.querySelector('#liquid-viscosity').addEventListener('input',event=>{amplitude=Number(event.target.value);document.querySelector('#liquid-value').textContent=amplitude;study.invalidate()});document.querySelector('#liquid-drop').addEventListener('click',()=>{if(!study.running()){x=600;y=350;drop();rings.at(-1).age=1.1}else drop(600,350);study.invalidate()});
let fontDataPromise=null;
function embeddedFont(){if(!fontDataPromise)fontDataPromise=Promise.all([fetch(new URL('../assets/display-bold.ttf',import.meta.url)).then(response=>{if(!response.ok)throw new Error('Local font unavailable');return response.blob()}).then(blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Font conversion failed'));reader.readAsDataURL(blob)})),fetch(new URL('../assets/Display-OFL.txt',import.meta.url)).then(response=>{if(!response.ok)throw new Error('Font notice unavailable');return response.text()})]).catch(error=>{fontDataPromise=null;throw error});return fontDataPromise}
async function exportArt(){const copy=art.cloneNode(true);try{const [fontData,notice]=await embeddedFont();copy.setAttribute('width','1200');copy.setAttribute('height','720');const background=document.createElementNS(NS,'rect');background.setAttribute('width','1200');background.setAttribute('height','720');background.setAttribute('fill','#ff5bbd');copy.insertBefore(background,copy.firstChild);const style=document.createElementNS(NS,'style');style.textContent=`@font-face{font-family:Display;src:url("${fontData}") format("truetype");font-weight:700;font-style:normal}`;copy.insertBefore(style,copy.firstChild);const metadata=document.createElementNS(NS,'metadata');metadata.textContent='Embedded Big Shoulders font notice:\n'+notice;copy.insertBefore(metadata,copy.firstChild);downloadSVG(copy,'07-liquid-letter.svg')}catch{study.notify('The local font could not be embedded. Please retry the export.')}}
study.onFrame(draw);study.onMotion(()=>study.invalidate());study.setReset(()=>{input.value='FLOW';input.dispatchEvent(new Event('input'));amplitude=36;document.querySelector('#liquid-viscosity').value='36';document.querySelector('#liquid-value').textContent='36';ripples.replaceChildren();rings.length=0;x=600;y=350;lastDrop=0;study.invalidate()});study.setExport(exportArt);
